import{_ as e,C as t,c as n,o as i,j as a,b as r,a0 as s,a as o,w as d,G as l,a1 as h}from"./chunks/framework.DKRgXLPU.js";const c=JSON.parse('{"title":"Op waarschijnlijkheid gebaseerde besluitvorming","description":"","frontmatter":{},"headers":[],"relativePath":"nl/education/tactics/probability.md","filePath":"nl/education/tactics/probability.md"}');const u=e({name:"nl/education/tactics/probability.md"},[["render",function(e,c,u,k,p,g){const b=t("Mermaid");return i(),n("div",null,[c[1]||(c[1]=a("h1",{id:"op-waarschijnlijkheid-gebaseerde-besluitvorming",tabindex:"-1"},[o("Op waarschijnlijkheid gebaseerde besluitvorming "),a("a",{class:"header-anchor",href:"#op-waarschijnlijkheid-gebaseerde-besluitvorming","aria-label":'Permalink to "Op waarschijnlijkheid gebaseerde besluitvorming"'},"​")],-1)),c[2]||(c[2]=a("p",null,"Bij tactisch denken op topniveau wordt gebruikgemaakt van waarschijnlijkheid om betere beslissingen te nemen. In plaats van te gokken of op je gevoel af te gaan, denk je systematisch na over je opties.",-1)),c[3]||(c[3]=a("div",{class:"tip custom-block"},[a("p",{class:"custom-block-title"},"Het Grote Idee"),a("p",null,[a("strong",null,"Denk in waarschijnlijkheden, niet in zekerheden."),o(" De beste beslissing is niet altijd de meest agressieve of de veiligste, maar de beslissing die je de beste verwachte waarde oplevert over vele vergelijkbare situaties.")])],-1)),(i(),r(h,null,{default:d(()=>[l(b,{id:"mermaid-11",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BBeslissingspunt%5D%20--%3E%20B%5BOptie%201%5D%0A%20%20%20%20A%20--%3E%20C%5BOptie%202%5D%0A%20%20%20%20A%20--%3E%20D%5BOptie%203%5D%0A%0A%20%20%20%20B%20--%3E%20E%5BSucceskans%5D%0A%20%20%20%20B%20--%3E%20F%5BBeloning%20bij%20succes%5D%0A%20%20%20%20B%20--%3E%20G%5BKosten%20bij%20mislukking%5D%0A%0A%20%20%20%20C%20--%3E%20H%5BSucceskans%5D%0A%20%20%20%20C%20--%3E%20I%5BBeloning%20bij%20succes%5D%0A%20%20%20%20C%20--%3E%20J%5BKosten%20bij%20mislukking%5D%0A%0A%20%20%20%20D%20--%3E%20K%5BSucceskans%5D%0A%20%20%20%20D%20--%3E%20L%5BBeloning%20bij%20succes%5D%0A%20%20%20%20D%20--%3E%20M%5BKosten%20bij%20mislukking%5D%0A%0A%20%20%20%20E%20--%3E%20N%5BVerwachte%20waarde%5D%0A%20%20%20%20F%20--%3E%20N%0A%20%20%20%20G%20--%3E%20N%0A%0A%20%20%20%20H%20--%3E%20O%5BVerwachte%20waarde%5D%0A%20%20%20%20I%20--%3E%20O%0A%20%20%20%20J%20--%3E%20O%0A%0A%20%20%20%20K%20--%3E%20P%5BVerwachte%20waarde%5D%0A%20%20%20%20L%20--%3E%20P%0A%20%20%20%20M%20--%3E%20P%0A%0A%20%20%20%20N%20--%3E%20Q%5BKies%20de%20beste%20elektrische%20auto%5D%0A%20%20%20%20O%20--%3E%20Q%0A%20%20%20%20P%20--%3E%20Q%0A%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20Q%20fill%3A%23fff4e1%0A"})]),fallback:d(()=>[...c[0]||(c[0]=[o(" Loading... ",-1)])]),_:1})),c[4]||(c[4]=s('<h2 id="het-basiskader" tabindex="-1">Het basiskader <a class="header-anchor" href="#het-basiskader" aria-label="Permalink to &quot;Het basiskader&quot;">​</a></h2><p>Elke worp bestaat uit drie onderdelen:</p><table tabindex="0"><thead><tr><th>component</th><th>Vraag</th><th>Voorbeeld</th></tr></thead><tbody><tr><td><strong>Kans op succes</strong></td><td>Hoe waarschijnlijk is het dat ik dit uitvoer?</td><td>70% slagingskans op deze afstand</td></tr><tr><td><strong>Beloning bij succes</strong></td><td>Wat levert het mij op?</td><td>Verover het punt, win de positie</td></tr><tr><td><strong>Kosten bij mislukte poging</strong></td><td>Wat heb ik te verliezen?</td><td>Geef de tegenstander een makkelijk punt</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">De formule</p><p><strong>Verwachte waarde = (Waarschijnlijkheid × Beloning) - ((1 - Waarschijnlijkheid) × Kosten)</strong></p><p>Goede beslissingen maximaliseren de verwachte waarde op de lange termijn.</p></div><h2 id="denken-in-waarschijnlijkheden" tabindex="-1">Denken in waarschijnlijkheden <a class="header-anchor" href="#denken-in-waarschijnlijkheden" aria-label="Permalink to &quot;Denken in waarschijnlijkheden&quot;">​</a></h2><p>Houd bij het kiezen tussen de verschillende opties rekening met het volgende:</p><ul><li>Wat is mijn realistische slagingskans voor elke optie?</li><li>Wat win ik als het werkt?</li><li>Wat zijn de kosten als het mislukt?</li><li>Hoe beïnvloedt de spelsituatie mijn keuze?</li></ul><p>De beste optie is niet altijd de meest agressieve of de veiligste, maar de optie die in veel vergelijkbare situaties het beste resultaat oplevert.</p><h2 id="ken-je-cijfers" tabindex="-1">Ken je cijfers <a class="header-anchor" href="#ken-je-cijfers" aria-label="Permalink to &quot;Ken je cijfers&quot;">​</a></h2><p>Om kansrekening te kunnen toepassen, moet je je werkelijke succespercentages kennen:</p><table tabindex="0"><thead><tr><th>Werptype</th><th>Afstand</th><th>Uw succespercentage</th></tr></thead><tbody><tr><td>Punt (dichtbij)</td><td>6-7m</td><td>___%</td></tr><tr><td>Punt (middelgroot)</td><td>8-9m</td><td>___%</td></tr><tr><td>Punt (lang)</td><td>10m+</td><td>___%</td></tr><tr><td>Fotografeer (van dichtbij)</td><td>6-7m</td><td>___%</td></tr><tr><td>Schieten (medium)</td><td>8-9m</td><td>___%</td></tr><tr><td>Schieten (lang)</td><td>10m+</td><td>___%</td></tr></tbody></table><p>Houd dit in de praktijk bij. Wees eerlijk: de meeste spelers overschatten hun succespercentage.</p><h2 id="aanpassen-aan-omstandigheden" tabindex="-1">Aanpassen aan omstandigheden <a class="header-anchor" href="#aanpassen-aan-omstandigheden" aria-label="Permalink to &quot;Aanpassen aan omstandigheden&quot;">​</a></h2><p>Uw basistarief verandert op basis van:</p><table tabindex="0"><thead><tr><th>Factor</th><th>Effect op het slagingspercentage</th></tr></thead><tbody><tr><td>Onbekend terrein</td><td>-10 tot -20%</td></tr><tr><td>Druksituatie</td><td>-5 tot -15%</td></tr><tr><td>Vermoeidheid</td><td>-5 tot -10%</td></tr><tr><td>Zelfvertrouwen (hoog)</td><td>+5 tot +10%</td></tr><tr><td>Recent succes</td><td>+5%</td></tr><tr><td>Recente mislukking</td><td>-5 tot -10%</td></tr></tbody></table><p>Wees realistisch over deze aanpassingen.</p><h2 id="het-boule-voordeelprincipe" tabindex="-1">Het Boule-voordeelprincipe <a class="header-anchor" href="#het-boule-voordeelprincipe" aria-label="Permalink to &quot;Het Boule-voordeelprincipe&quot;">​</a></h2><p>Als je meer boules over hebt dan je tegenstander:</p><p><strong>Prioriteit 1: Het punt veiligstellen</strong></p><ul><li>Zorg er allereerst voor dat je minstens één punt vasthoudt.</li><li>Wees niet hebzuchtig voordat je de basis hebt veiliggesteld.</li></ul><p><strong>Prioriteit 2: Maximaliseer punten met een berekend risico</strong></p><ul><li>Als je eenmaal winst hebt gemaakt, beoordeel dan of je nog meer punten kunt bijkopen.</li><li>Elke extra worp is een afweging tussen risico en beloning.</li><li>Verander een veilige overwinning met 2 punten verschil niet in een nederlaag door te veel risico te nemen.</li></ul><p><strong>Nog maar weinig boules over:</strong> Elke worp moet raak zijn. Veilige zetten zijn misschien niet genoeg - overweeg opties met een hogere beloning om uiteindelijk toch nog een kans te maken.</p><h2 id="het-une-boule-devant-principe" tabindex="-1">Het ‘Une Boule Devant’-principe <a class="header-anchor" href="#het-une-boule-devant-principe" aria-label="Permalink to &quot;Het ‘Une Boule Devant’-principe&quot;">​</a></h2><p>Een boule voor de jack (tussen de jack en de tegenstander) is extreem waardevol:</p><ul><li>Het blokkeert directe aanwijslijnen.</li><li>Het dwingt tegenstanders om eromheen of eroverheen te gaan.</li><li>Het kan inkomende boules afbuigen.</li><li>Het is een &quot;goudmijn&quot; - het is de moeite waard om te beschermen.</li></ul><p><strong>Tactische implicatie:</strong> Soms is het beter om een blokkerende boule te plaatsen dan te proberen er zo dicht mogelijk bij te komen.</p><h2 id="risicotolerantie-per-spelstatus" tabindex="-1">Risicotolerantie per spelstatus <a class="header-anchor" href="#risicotolerantie-per-spelstatus" aria-label="Permalink to &quot;Risicotolerantie per spelstatus&quot;">​</a></h2><h3 id="met-tijdslimiet" tabindex="-1">Met tijdslimiet <a class="header-anchor" href="#met-tijdslimiet" aria-label="Permalink to &quot;Met tijdslimiet&quot;">​</a></h3><p>Bij een tijdslimiet is het scoreverschil van belang:</p><table tabindex="0"><thead><tr><th>Scoresituatie</th><th>Risicobenadering</th></tr></thead><tbody><tr><td>Met een voorsprong van 4+</td><td>Zeer conservatief - bescherm het lood, laat de klok lopen</td></tr><tr><td>Met een voorsprong van 1-3</td><td>Conservatief - geef geen punten weg</td></tr><tr><td>Gebonden</td><td>Evenwichtig - berekende risico&#39;s</td></tr><tr><td>Achterstand van 1-3</td><td>Agressief - moet terrein winnen.</td></tr><tr><td>Achterstand van 4+</td><td>Zeer agressief - moet risico&#39;s nemen, de tijd dringt.</td></tr></tbody></table><h3 id="zonder-tijdslimiet" tabindex="-1">Zonder tijdslimiet <a class="header-anchor" href="#zonder-tijdslimiet" aria-label="Permalink to &quot;Zonder tijdslimiet&quot;">​</a></h3><p>Als er geen tijdsdruk is:</p><ul><li>Houd vast aan je spelplan - verander je strategie niet zomaar vanwege de score.</li><li>De score zal schommelen - vertrouw op je aanpak.</li><li>Overweeg alleen je spelplan aan te passen als het duidelijk niet werkt tegen deze tegenstander.</li><li>Paniek en veranderingen achterstand maken de situatie vaak alleen maar erger.</li></ul><h3 id="aanpassingen-aan-het-eindspel" tabindex="-1">Aanpassingen aan het eindspel <a class="header-anchor" href="#aanpassingen-aan-het-eindspel" aria-label="Permalink to &quot;Aanpassingen aan het eindspel&quot;">​</a></h3><p><strong>Als winnen aan deze kant betekent dat we de wedstrijd winnen:</strong></p><ul><li>Wees conservatiever.</li><li>Loop niet het risico om meerdere punten weg te geven.</li><li>Een enkel punt zou voldoende kunnen zijn.</li></ul><p><strong>Als dit de wedstrijd betekent:</strong></p><ul><li>Neem grotere risico&#39;s</li><li>Je moet meerdere punten scoren.</li><li>Veilig spelen zal je niet redden.</li></ul><h2 id="veelvoorkomende-fouten-bij-kansberekening" tabindex="-1">Veelvoorkomende fouten bij kansberekening <a class="header-anchor" href="#veelvoorkomende-fouten-bij-kansberekening" aria-label="Permalink to &quot;Veelvoorkomende fouten bij kansberekening&quot;">​</a></h2><h3 id="_1-overmoed" tabindex="-1">1. Overmoed <a class="header-anchor" href="#_1-overmoed" aria-label="Permalink to &quot;1. Overmoed&quot;">​</a></h3><p>&quot;Die shot kan ik wel maken&quot; - maar lukt het je ook 7 van de 10 keer? Wees eerlijk.</p><h3 id="_2-basisrente-negeren" tabindex="-1">2. Basisrente negeren <a class="header-anchor" href="#_2-basisrente-negeren" aria-label="Permalink to &quot;2. Basisrente negeren&quot;">​</a></h3><p>Je schotpercentage verandert niet omdat het moment belangrijk is.</p><h3 id="_3-de-denkfout-van-de-verzonken-kosten" tabindex="-1">3. De denkfout van de verzonken kosten <a class="header-anchor" href="#_3-de-denkfout-van-de-verzonken-kosten" aria-label="Permalink to &quot;3. De denkfout van de verzonken kosten&quot;">​</a></h3><p>&quot;Ik heb al twee keer misgeschoten, ik moet blijven schieten&quot; - elke worp is onafhankelijk.</p><h3 id="_4-vertekening-van-de-uitkomst" tabindex="-1">4. Vertekening van de uitkomst <a class="header-anchor" href="#_4-vertekening-van-de-uitkomst" aria-label="Permalink to &quot;4. Vertekening van de uitkomst&quot;">​</a></h3><p>Een riskante actie die lukte, bleef riskant. Een veilige actie die mislukte, was nog steeds de juiste.</p><h3 id="_5-de-opties-van-de-tegenstander-negeren" tabindex="-1">5. De opties van de tegenstander negeren <a class="header-anchor" href="#_5-de-opties-van-de-tegenstander-negeren" aria-label="Permalink to &quot;5. De opties van de tegenstander negeren&quot;">​</a></h3><p>Bedenk wat ze zullen doen na je worp, of die nu succesvol is of niet.</p><h2 id="praktische-toepassing" tabindex="-1">Praktische toepassing <a class="header-anchor" href="#praktische-toepassing" aria-label="Permalink to &quot;Praktische toepassing&quot;">​</a></h2><h3 id="voor-elke-worp" tabindex="-1">Voor elke worp <a class="header-anchor" href="#voor-elke-worp" aria-label="Permalink to &quot;Voor elke worp&quot;">​</a></h3><ol><li><strong>Bepaal de opties</strong> (richten, schieten, blokkeren, enz.)</li><li><strong>Schat de kans op succes</strong> voor elk</li><li><strong>Denk na over de mogelijke uitkomsten</strong> (succes en mislukking)</li><li><strong>Houd rekening met de spelstatus</strong> (score, resterende boules)</li><li><strong>Kies</strong> de optie met de beste verwachte waarde.</li><li><strong>Zet je er volledig voor in</strong> - geen twijfels tijdens de uitvoering.</li></ol><h3 id="intuitie-opbouwen" tabindex="-1">Intuïtie opbouwen <a class="header-anchor" href="#intuitie-opbouwen" aria-label="Permalink to &quot;Intuïtie opbouwen&quot;">​</a></h3><p>Na verloop van tijd wordt het denken in termen van waarschijnlijkheid intuïtief:</p><ul><li>Houd uw resultaten eerlijk bij.</li><li>Evalueer beslissingen na de wedstrijden.</li><li>Merk patronen op in uw succespercentages.</li><li>Pas je mentale model aan.</li></ul><h2 id="belangrijkste-conclusie" tabindex="-1">Belangrijkste conclusie <a class="header-anchor" href="#belangrijkste-conclusie" aria-label="Permalink to &quot;Belangrijkste conclusie&quot;">​</a></h2><blockquote><p>Goede beslissingen leiden niet altijd tot goede resultaten. Maar goede beslissingen leiden op de lange termijn wel tot betere resultaten.</p></blockquote><p>Denk in waarschijnlijkheden. Ken je getallen. Maak een verstandige keuze, geen hoopvolle.</p>',59))])}]]);export{c as __pageData,u as default};
